 for(const name of ['edmmap.js','edmui.js','opsnow.js','opsnow_tallyview.js','opsnow_hardpoints.mjs','opsnow_landing.mjs','opsnow_landing_core.mjs','opsnow_landing_worker.mjs','opsnow_landing_demo.mjs','opsnow_landing_sim.mjs','opsnow_landing_audit.mjs','opsnow_landing_windows.mjs','opsnow_landing_space.mjs']){const expected=source.files.find(f=>f.path===name)?.sha256;if(!expected||(digest(Buffer.from(entries[name]),'sha256')!==expected&&digest(Buffer.from(entries[name]),'sha256')!==digest(await readFile('drilling/'+name),'sha256')))throw Error('Production '+name+' changed since the reviewed patch; rebase before publishing.');}
 for(const name of ['index.html','style.css','app.mjs','core.mjs','scene.mjs','fallback.mjs','reservoir.mjs','reservoir-view.mjs','landing.mjs','landing-view.mjs','probe.mjs','probe-view.mjs']){const path='directional-drilling/'+name;if(!manifest['/'+path])continue;const served=await staticFile(origin,'/'+path),expected=source.files.find(f=>f.path===path)?.sha256;if(digest(served)!==manifest['/'+path]||!expected||(digest(served,'sha256')!==expected&&digest(served,'sha256')!==digest(await readFile('drilling/'+path),'sha256')))throw Error('Production '+path+' changed since the reviewed game patch.');}
 for(const path of ['opsnow_views.js','wpg_core.js','fluids.js','opsnow_engineering.mjs','opsnow_engineering_worker.mjs','opsnow_engineering.css','opsnow_well_workspace.mjs','opsnow_performance.mjs','opsnow_performance_core.mjs','opsnow_performance.css','opsnow_landing_dock.mjs','opsnow_landing_status.mjs','opsnow_landing_dock.css']){if(!manifest['/'+path])continue;const served=await staticFile(origin,'/'+path),expected=source.files.find(f=>f.path===path)?.sha256;if(digest(served)!==manifest['/'+path]||!expected||(digest(served,'sha256')!==expected&&digest(served,'sha256')!==digest(await readFile('drilling/'+path),'sha256')))throw Error('Production '+path+' changed since the reviewed Ops integration.');}
 if(manifest['/landing-game/index.html']){const path='landing-game/index.html',served=await staticFile(origin,'/'+path),expected=source.files.find(f=>f.path===path)?.sha256;if(digest(served)!==manifest['/'+path]||!expected||(digest(served,'sha256')!==expected&&digest(served,'sha256')!==digest(await readFile('drilling/'+path),'sha256')))throw Error('The legacy simulation entry changed; rebase before replacing its link.');}
 overlay.set('/index.html',Buffer.from(patchWellFolderGameHtml(patchGameHtml(entries['index.html']))));
 let ops=patchWorkspaceHtml(entries['ops.html']);if(!ops.includes('./opsnow.js'))throw Error('Ops entry has no known script.');const opsScript=(await readFile('drilling/ops.html','utf8')).match(/\.\/opsnow\.js(?:\?[^"']*)?/)?.[0];if(!opsScript)throw Error('Reviewed Ops entry has no known script.');ops=ops.replace(/\.\/opsnow\.js(?:\?[^"']*)?/g,()=>opsScript);if(!ops.includes('./opsnow_watch_zones.css'))ops=ops.replace('</head>','<link rel="stylesheet" href="./opsnow_watch_zones.css?v=watch1"></head>');overlay.set('/ops.html',Buffer.from(ops));
