 for(const name of await readdir('drilling/engineering')){if(!/^[a-z0-9-]+\.mjs$/.test(name))throw Error('Unexpected engineering asset.');const path='engineering/'+name,bytes=await readFile('drilling/'+path);if(manifest['/'+path]){const served=await staticFile(origin,'/'+path),expected=source.files.find(f=>f.path===path)?.sha256;if(digest(served)!==manifest['/'+path]||!expected||(digest(served,'sha256')!==expected&&digest(served,'sha256')!==digest(bytes,'sha256')))throw Error('Production engineering kernel changed since review: '+path);}overlay.set('/'+path,bytes);}
 for(const name of ['opsnow_reservoir.mjs','opsnow_mwd_battery.mjs','opsnow_views.js','opsnow_watch_zones.mjs','opsnow_watch_3d.mjs','opsnow_watch_zones.css','wpg_core.js','opsnow_engineering.mjs','opsnow_engineering_worker.mjs','opsnow_engineering.css','opsnow_well_workspace.mjs','opsnow_performance.mjs','opsnow_performance_core.mjs','opsnow_performance.css','edmmap.js','edmui.js','edm_field_check.mjs','edm_field_check_core.mjs','edm_field_check_worker.mjs','opsnow_hardpoints.mjs','opsnow_operation_report.mjs','opsnow_landing_dock.mjs','opsnow_landing_status.mjs','opsnow_landing_dock.css','opsnow_landing.mjs','opsnow_landing_core.mjs','opsnow_landing_worker.mjs','opsnow_landing_demo.mjs','opsnow_landing_audit.mjs','opsnow_landing_windows.mjs','opsnow_landing_space.mjs','opsnow_landing_joints.mjs','opsnow_landing_schedule.mjs','opsnow_landing_sim.mjs','opsnow_measured_upload.mjs','opsnow.js','opsnow_joint_metrics.mjs','opsnow_tally_compare.mjs','data/dr101l-wb04-measured-tally.json','opsnow_tallyview.js','opsnow_survey_alert.mjs','opsnow_survey_alert.css','opsnow_pumps.mjs','opsnow_pumps.css'])overlay.set('/'+name,await readFile('drilling/'+name));
 async function addModule(dir,prefix){for(const entry of await readdir(dir,{withFileTypes:true})){if(entry.isDirectory())await addModule(dir+'/'+entry.name,prefix+'/'+entry.name);else overlay.set(prefix+'/'+entry.name,await readFile(dir+'/'+entry.name));}}
 await addModule('drilling/well-folder','/well-folder');
 await addModule('drilling/bha-builder','/bha-builder');
 await addModule('drilling/directional-drilling','/directional-drilling');
 overlay.set('/landing-game/index.html',await readFile('drilling/landing-game/index.html'));
 const candidate={...manifest};for(const [path,body]of overlay)candidate[path]=digest(body);
 for(const path of oldKeys)if(!overlay.has(path)&&candidate[path]!==manifest[path])throw Error('An unrelated production file changed.');
 if(oldKeys.some(path=>!(path in candidate)))throw Error('A production file was removed.');
 const latestSite=await api('/sites/'+site.id);if(latestSite.published_deploy?.id!==deploy.id)throw Error('Production moved during preflight; retry from the new baseline.');
